from __future__ import annotations

import gc
import json
import statistics
import time
import tracemalloc
from pathlib import Path
import fq_shared_cz_support_20261122 as support

out=Path('/private/tmp/fq-shared-cz-resources-20261122.json')
assert not out.exists()
rows=[]
for width,family,topology in ((6,'qft','grid'),(6,'repetition','ring'),(12,'qft','grid')):
    source=support.fixture(width,family,topology,support.NONCES[0])
    def run(variant,trace=False):
        adapter=support.adapter_for('flagquantum-target-artifact')
        peak=None
        with support.selected(variant):
            if trace:tracemalloc.start()
            try:
                started=time.perf_counter()
                payload=adapter.execute('route',source,11)
                elapsed=time.perf_counter()-started
                if trace:peak=tracemalloc.get_traced_memory()[1]
            finally:
                if trace:tracemalloc.stop()
        return payload,elapsed,peak
    for _ in range(2):
        for variant in ('baseline','candidate'):run(variant)
    samples={v:[] for v in ('baseline','candidate')}
    payloads={}
    for iteration in range(9):
        for variant in (('baseline','candidate') if iteration%2==0 else ('candidate','baseline')):
            payload,elapsed,_=run(variant)
            samples[variant].append(elapsed)
            payloads[variant]=payload
    peaks={}
    for variant in ('baseline','candidate'):
        gc.collect()
        _,_,peaks[variant]=run(variant,trace=True)
    medians={v:statistics.median(values) for v,values in samples.items()}
    metrics={v:support.accept(p,source) for v,p in payloads.items()}
    assert metrics['baseline']==metrics['candidate']
    assert payloads['baseline']['operations']==payloads['candidate']['operations']
    row={'case':[width,family,topology],'samples_seconds':samples,'median_seconds':medians,'compiler_stage_traced_python_peak_bytes':peaks,'metrics':metrics,'time_ratio':medians['candidate']/medians['baseline'],'passes_time_gate':medians['candidate']<=.95*medians['baseline'],'passes_peak_gate':peaks['candidate']<=peaks['baseline']}
    rows.append(row)
    print(json.dumps(row),flush=True)
report={'scope':'Shared-host inspected development control, not qualified latency, RSS, significance or SDK ranking','warmups':2,'retained_rounds':9,'order':'alternating baseline/candidate by round','rows':rows,'passes_declared_resource_admission':all(r['passes_time_gate'] and r['passes_peak_gate'] for r in rows),'driver_source':Path(__file__).read_text(),'support_source':Path('/private/tmp/fq_shared_cz_support_20261122.py').read_text()}
out.write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps({'passes_declared_resource_admission':report['passes_declared_resource_admission']}))

